def link_signed_contracts(apps, schema_editor):
    """Contracts analyzed from a signed PDF point back at their request."""
    Contract = apps.get_model("db", "Contract")
    SignatureRequest = apps.get_model("db", "ContractSignatureRequest")
    pairs = SignatureRequest.objects.filter(analysis_contract__isnull=False).values_list("id", "analysis_contract_id")
